'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const source=fs.readFileSync('JS/western-completion.js','utf8'),DAY=86400000,orbs={Sun:15,Moon:12,Mercury:7,Venus:7,Mars:7,Jupiter:9,Saturn:9},results=[];
function model(moon,sun){const start=Date.parse('2026-10-01T00:00:00Z'),ctx={JYWestern:{position(k,t){return {longitude:((k==='Moon'?moon+10*(t-start)/DAY:k==='Sun'?sun+(t-start)/DAY:165)+360)%360};}}};vm.createContext(ctx);vm.runInContext(source,ctx);return ctx.JYWesternCompletion.moonOrbTimeline({input:{utc:new Date(start).toISOString()}},orbs);}
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
test('linear fixture: enters orb before Moon ingress although exact conjunction is after ingress',()=>{const r=model(20,34);assert.equal(r.noApplicationBeforeIngress,false);assert.equal(r.currentApplications.length,0);const e=r.entries.find(e=>e.planet==='Sun'&&e.angle===0);assert(e);assert(Math.abs(Date.parse(e.fromUTC)-Date.parse(r.startUTC)-DAY/18)<500);assert(Date.parse(e.fromUTC)<Date.parse(r.nextIngress.utc));assert.equal(e.applyingAtEntry,true);assert(e.entryErrorDegrees<.0001);});
test('linear fixture: no current application or orb entry before ingress is identified',()=>{const r=model(20,60);assert.equal(r.noApplicationBeforeIngress,true);assert.equal(r.entries.length,0);assert.equal(r.outOfAllOrbsAtChart,true);});
test('linear fixture: contact after ingress cannot be included in this sign',()=>{const r=model(29.9,45);assert.equal(r.entries.length,0);assert.equal(r.noApplicationBeforeIngress,true);});
test('linear fixture: zodiac wrap does not corrupt Moon ingress or intervals',()=>{const r=model(359,16);assert.equal(r.nextIngress.to,0);assert(Math.abs(Date.parse(r.nextIngress.utc)-Date.parse(r.startUTC)-DAY/10)<500);});
const {environment,examples}=require('./native-fixtures-20261003.cjs'),c=environment().ctx,x=examples(c);
test('actual Astronomy Engine horary integrates full future orb-entry calculation with distinct exact convention',()=>{const w=c.JYWestern.compute({...x.input,utc:'2026-10-01T14:06:00Z',reference:'2026-10-01T14:06:00Z',chartPurpose:'horary',horaryHouse:7,horaryDays:1});const m=w.horary.moon.orbEntryBeforeIngress;assert.equal(m.status,'calculated');assert(m.nextIngress);assert.equal(typeof m.noApplicationBeforeIngress,'boolean');for(const e of m.entries){assert(Date.parse(e.fromUTC)<Date.parse(m.nextIngress.utc));assert(e.entryErrorDegrees<.001);}results.push({name:'actual-orb-entry-fixture',status:'passed',entries:m.entries});});
fs.writeFileSync('docs/western-moon-orb-validation-20261003.json',JSON.stringify({testedAt:new Date().toISOString(),fixtures:'Four synthetic linear ephemerides test mathematical roots; one actual Astronomy Engine horary tests integration. Synthetic fixtures are not claimed as real astronomical charts.',results},null,2));
